  + TX('<b>נדרש:</b> כמה מיכל חייבת לרון, ומה יקרה אם היא לא תשלם?') + '</p></div>'
  + TABLES(['מה בודקים', 'התוצאה', 'איך ולמה'], [
      ['<b>החוב של מיכל</b>', '10,000 דולר', '$Q × (S_{T} − K) = 1,000 × (90 − 80)$'],
      ['<b>עסקה ישירה</b>', 'רון מפסיד 10,000', 'החוזה שווה לרון כסף, ומיכל לא משלמת: סיכון צד נגדי'],
      ['<b>עסקה דרך מסלקה</b>', 'רון מקבל 10,000', 'המסלקה משלמת, מתוך [[margin|הביטחונות (Margin)]] שמיכל הפקידה']], 'mtab', 1)
  + DEF('סיכון צד נגדי (Counterparty risk)', 'הסיכון שהצד השני לא ישלם, כשהחוזה שווה לכם כסף.', 'בעסקה ישירה, 10,000 הדולר של רון תלויים ביכולת של מיכל לשלם.', 4, trm='cpty', cls='mini')
